pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log lg;

    function setUp() public { lg = new Log(); c = new C(address(lg)); }

    function testFuzz_property(uint256 amount, address actor, uint256 unlockTime) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0 && amount <= 100 ether);
        unlockTime = bound(unlockTime, 0, 2 * 10 ** 9);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        // deposit must be reflected in the holder's balance
        (, uint256 bal) = c.Acc(actor);
        assertTrue(bal == amount);

        // and the deposit must be logged: the last History entry records Val == amount
        uint256 len = logLen();
        assertTrue(len >= 1);
        (,,,, uint256 val) = entry(len - 1);
        assertTrue(val == amount);
    }

    uint256 internal unused;

    function logLen() internal view returns (uint256) {
        // probe length by scanning from a known bound; History getter is index-based
        uint256 n = 0;
        while (true) {
            try this.probe(n) {
                n++;
                if (n > 1000) return n;
            } catch {
                return n;
            }
        }
    }

    function probe(uint256 i) external view {
        lg.History(i);
    }

    function entry(uint256 i) internal view returns (address, string memory, uint256, uint256) {
        return lg.History(i);
    }
}

