pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 0, type(uint256).max - 1);

        // first deposit fills the balance up to (type(uint256).max - amount)
        uint256 v1 = type(uint256).max - amount; // >= 1
        // second deposit would push the true sum one wei past 2**256-1
        uint256 v2;
        unchecked { v2 = amount + 1; } // v2 <= type(uint256).max

        uint256 total;
        unchecked { total = v1 + v2; } // == 2**256, computed wrapped-safe
        vm.deal(actor, type(uint256).max);

        vm.prank(actor);
        c.Put{value: v1}(0);
        uint256 before = c.Acc(actor).balance;

        // the overflowing deposit: the reference must refuse it (balance intact);
        // a guard-less version lets the balance wrap downward.
        vm.prank(actor);
        try c.Put{value: v2}(0) { /* deposit accepted or wrapped */ } catch { /* refused */ }

        // GENERAL RULE: an account's balance is never decreased by a deposit attempt.
        assertTrue(c.Acc(actor).balance >= before);
    }
}

