pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 firstAmount, uint256 secondAmount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(firstAmount > 0 && secondAmount > 0);
        vm.assume(firstAmount <= type(uint256).max - secondAmount);

        vm.deal(actor, firstAmount + secondAmount);

        // First deposit always succeeds in both versions.
        vm.prank(actor);
        c.Put{value: firstAmount}(0);

        // Second deposit: reference reverts on overflow, mutant wraps silently.
        bool ok;
        vm.prank(actor);
        try c.Put{value: secondAmount}(0) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: after any Put call, the holder's balance never drops
        // below the balance held before that call (either the call reverts, or
        // the deposit adds without wrapping).
        assertTrue(!ok || c.Acc(actor).balance >= firstAmount);
    }
}
